#include "native.h"
#include <psapi.h>
static uint64_t filetime_value(FILETIME f){ULARGE_INTEGER u;u.LowPart=f.dwLowDateTime;u.HighPart=f.dwHighDateTime;return u.QuadPart;}
int profile_process(DWORD pid,int seconds){HANDLE p=OpenProcess(PROCESS_QUERY_INFORMATION|PROCESS_VM_READ,FALSE,pid);if(!p)return 1;FILETIME c,e,k,u;GetProcessTimes(p,&c,&e,&k,&u);uint64_t cpu0=filetime_value(k)+filetime_value(u),wall0=GetTickCount64();size_t low=(size_t)-1,high=0,privLow=(size_t)-1,privHigh=0;DWORD gdi0=GetGuiResources(p,GR_GDIOBJECTS),user0=GetGuiResources(p,GR_USEROBJECTS);for(int i=0;i<seconds;i++){PROCESS_MEMORY_COUNTERS_EX m={0};m.cb=sizeof(m);if(GetProcessMemoryInfo(p,(PROCESS_MEMORY_COUNTERS*)&m,sizeof(m))){if(m.WorkingSetSize<low)low=m.WorkingSetSize;if(m.WorkingSetSize>high)high=m.WorkingSetSize;if(m.PrivateUsage<privLow)privLow=m.PrivateUsage;if(m.PrivateUsage>privHigh)privHigh=m.PrivateUsage;}Sleep(1000);}GetProcessTimes(p,&c,&e,&k,&u);double cpu=(filetime_value(k)+filetime_value(u)-cpu0)/10000.0/(GetTickCount64()-wall0)*100;printf("{\"pid\":%lu,\"seconds\":%d,\"workingSetMinMiB\":%.4f,\"workingSetMaxMiB\":%.4f,\"privateMinMiB\":%.4f,\"privateMaxMiB\":%.4f,\"idleSingleCoreCpuPercent\":%.5f,\"gdiStart\":%lu,\"gdiEnd\":%lu,\"userStart\":%lu,\"userEnd\":%lu}\n",pid,seconds,low/1048576.0,high/1048576.0,privLow/1048576.0,privHigh/1048576.0,cpu,gdi0,GetGuiResources(p,GR_GDIOBJECTS),user0,GetGuiResources(p,GR_USEROBJECTS));CloseHandle(p);return 0;}
